const cmds = [
  ["siblings", "ls -la \"$ARCHON_HORIZON_SESSION_DIR/..\""],
  ["usage", "\"$HORIZON_BIN\" usage --json"],
  ["ps", "\"$HORIZON_BIN\" ps"],
  ["log", "\"$HORIZON_GIT\" log --oneline -15"]
];
const rs = await Promise.all(cmds.map(async ([name, cmd]) => {
  const r = await tools.exec_command({
    cmd,
    workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
    yield_time_ms: 10000,
    max_output_tokens: 20000
  });
  return {name, output: r.output, exit_code: r.exit_code};
}));
for (const r of rs) {
  text(`=== ${r.name} (exit ${r.exit_code}) ===\n${r.output}`);
}

const files = [
  ".claude/skills/horizon-inbox/SKILL.md",
  ".claude/skills/task-status/SKILL.md",
  ".claude/skills/project-git/SKILL.md",
  ".claude/skills/hgraph/SKILL.md",
  ".claude/skills/blueprint-conventions/SKILL.md"
];
const rs = await Promise.all(files.map(async (file) => {
  const r = await tools.exec_command({
    cmd: `wc -l "${file}"`,
    workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
    yield_time_ms: 10000,
    max_output_tokens: 1000
  });
  return r.output.trim();
}));
for (const out of rs) text(out);

const files = [
  ".claude/skills/horizon-inbox/SKILL.md",
  ".claude/skills/task-status/SKILL.md",
  ".claude/skills/project-git/SKILL.md",
  ".claude/skills/hgraph/SKILL.md",
  ".claude/skills/blueprint-conventions/SKILL.md"
];
const rs = await Promise.all(files.map(async (file) => {
  const r = await tools.exec_command({
    cmd: `sed -n '1,360p' "${file}"`,
    workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
    yield_time_ms: 10000,
    max_output_tokens: 30000
  });
  return {file, output: r.output};
}));
for (const r of rs) text(`=== ${r.file} ===\n${r.output}`);

const r = await tools.exec_command({
  cmd: "\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 10000,
  max_output_tokens: 40000
});
text(r.output);

const r = await tools.exec_command({
  cmd: "\"$HORIZON_BIN\" inbox list --mine --status open --kind protection --json 2>/dev/null | jq '{attention, items: [.items[] | {id, author, audience, owner_task, body, scope, comments: [.comments[] | {author, at, body}]}], warnings}'",
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon",
  yield_time_ms: 10000,
  max_output_tokens: 50000
});
text(r.output);

